import{c as a,Q as t,j as o,m as i}from"./chunks/framework.BvWD_EvC.js";const u=JSON.parse('{"title":"Mass Tag Editor","description":"","frontmatter":{},"headers":[],"relativePath":"guide/using-librislog/mass-tag-editor.md","filePath":"guide/using-librislog/mass-tag-editor.md","lastUpdated":1793278114000}'),s={name:"guide/using-librislog/mass-tag-editor.md"};function r(n,e,l,d,g,c){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="mass-tag-editor" tabindex="-1">Mass Tag Editor <a class="header-anchor" href="#mass-tag-editor" aria-label="Permalink to &quot;Mass Tag Editor&quot;">​</a></h1><p>The Mass Tag Editor lets you add or remove tags on many books at once. It is accessible from <strong>Profile → Manage my data → Mass Tag Editor</strong>.</p><p>Tags are the recommended way to group books (for example a shelf, a series, or a reading project). This page makes applying them to a large library practical.</p><h2 id="filtering-books" tabindex="-1">Filtering books <a class="header-anchor" href="#filtering-books" aria-label="Permalink to &quot;Filtering books&quot;">​</a></h2><p>Use the filter bar to narrow the list:</p><ul><li><strong>Search</strong> — full text search, including field prefixes such as <code>tag:cars</code> or <code>author:&quot;Jane Driver&quot;</code> and negation with <code>-</code>.</li><li><strong>Reading status</strong>, <strong>Medium</strong>, <strong>Acquisition status</strong> — standard library filters.</li><li><strong>Tag</strong> — show only books that have (or lack) a specific tag, using the <strong>Has tag</strong> / <strong>Lacks tag</strong> toggle.</li></ul><p>The table shows the title, author, current tags, and reading status of each book. Click a title to open it in the library.</p><h2 id="selecting-books" tabindex="-1">Selecting books <a class="header-anchor" href="#selecting-books" aria-label="Permalink to &quot;Selecting books&quot;">​</a></h2><ul><li>Check individual rows, or use the header checkbox to select all books on the current page.</li><li><strong>Load more</strong> appends the next page without losing your selection.</li><li><strong>Select all N matching</strong> (shown when more than one page exists) selects every book that matches the current filters, even those not yet loaded. The action bar then shows the total count.</li><li><strong>Clear selection</strong> leaves the all-matching mode.</li></ul><p>Up to 500 books are processed per request; larger selections are split automatically and progress is shown.</p><h2 id="adding-and-removing-tags" tabindex="-1">Adding and removing tags <a class="header-anchor" href="#adding-and-removing-tags" aria-label="Permalink to &quot;Adding and removing tags&quot;">​</a></h2><p>The action bar at the bottom of the screen has two fields:</p><ul><li><strong>Add tags</strong> — tags to apply to every selected book.</li><li><strong>Remove tags</strong> — tags to remove from every selected book.</li></ul><p>A tag cannot be both added and removed in the same operation. Suggestions come from your existing tags.</p><h3 id="case-differences" tabindex="-1">Case differences <a class="header-anchor" href="#case-differences" aria-label="Permalink to &quot;Case differences&quot;">​</a></h3><p>Tag matching is exact, including capitalization. If you type a tag that differs only in capitalization from an existing tag (for example <code>sci-fi</code> next to <code>Sci-Fi</code>), a warning appears with a one-click shortcut to reuse the existing spelling. The warning is advisory; the tag you typed is still created if you proceed.</p><h2 id="confirmation-and-result" tabindex="-1">Confirmation and result <a class="header-anchor" href="#confirmation-and-result" aria-label="Permalink to &quot;Confirmation and result&quot;">​</a></h2><p>Click <strong>Apply to selected</strong> to open a confirmation dialog showing the affected count, the tags to add and remove, and a preview of the first ten affected titles (or a summary when all matching books are selected). Confirm to apply.</p><p>After a successful run, a summary toast reports how many books changed, how many tag links were added and removed, and which tags were deleted because they no longer had any book.</p><h2 id="orphan-tag-cleanup" tabindex="-1">Orphan tag cleanup <a class="header-anchor" href="#orphan-tag-cleanup" aria-label="Permalink to &quot;Orphan tag cleanup&quot;">​</a></h2><p>When a tag ends up on no book after a removal, it is deleted automatically, the same as when editing a single book or deleting one.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>At most 500 books per request; larger selections are chunked automatically.</li><li>At most 50 tags per add or remove list.</li><li>Tag names must not contain commas.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/next/guide/using-librislog/data-hygiene.html">Data Hygiene</a> — bulk-fix missing metadata.</li><li><a href="/next/guide/using-librislog/library.html">Library</a> — search and filter syntax, including <code>tag:</code>.</li></ul>',25)])])}const m=a(s,[["render",r]]);export{u as __pageData,m as default};
